function stripMatchingQuotes(value: string): string {
  if (value.length >= 2) {
    const first = value[0];
    const last = value[value.length - 1];
    if ((first === '"' && last === '"') || (first === "'" && last === "'")) return value.slice(1, -1);
  }
  return value;
}

async function loadExplicitSecrets(options: SessionSanitizationOptions): Promise<string[]> {
  const values: string[] = [];
  for (const input of options.secret ?? []) {
    const trimmed = input.trim();
    if (!trimmed) continue;
    const maybePath = resolveFromCwd(trimmed, options.cwd);
    if (await pathExists(maybePath)) {
      values.push(
        ...(await readFile(maybePath, "utf8"))
          .split(/\r?\n/)
          .map((line) => line.trim())
          .filter(Boolean),
      );
    } else {
      values.push(trimmed);
    }
  }
  return values;
}

function buildLiteralSecrets(inputs: string[]): LiteralSecret[] {
  const uniqueValues = [...new Set(inputs.map((input) => input.trim()).filter(Boolean))];
  return uniqueValues
    .sort((a, b) => b.length - a.length)
    .map((value, index) => ({ value, replacement: `[REDACTED_SECRET_${index + 1}]` }));
}

function resolveFromCwd(path: string, cwd = process.cwd()): string {
  return isAbsolute(path) ? path : resolve(cwd, path);
}

function redactText(text: string, secrets: LiteralSecret[]): { text: string; replacements: number } {
  let redacted = text;
  let replacements = 0;
  for (const secret of secrets) {
    const count = countOccurrences(redacted, secret.value);
    if (count === 0) continue;
    redacted = redacted.replaceAll(secret.value, secret.replacement);
    replacements += count;
  }
  return { text: redacted, replacements };
}

function countOccurrences(text: string, value: string): number {
  if (!value) return 0;
  return text.split(value).length - 1;
}

